package com.tripmateai.service.impl; import com.tripmateai.dto.request.nearby.*; import com.tripmateai.dto.response.nearby.NearbyPlaceResponse; import com.tripmateai.entity.*; import com.tripmateai.exception.*; import com.tripmateai.mapper.NearbyPlaceMapper; import com.tripmateai.repository.*; import com.tripmateai.service.NearbyPlaceService; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class NearbyPlaceServiceImpl implements NearbyPlaceService {private final DestinationRepository destinations;private final NearbyPlaceRepository places; private Destination destination(Long id){return destinations.findById(id).orElseThrow(()->new ResourceNotFoundException("Destination not found"));} private NearbyPlace place(Long d,Long id){return places.findByIdAndDestination(id,destination(d)).orElseThrow(()->new ResourceNotFoundException("Nearby place not found"));} private void apply(NearbyPlace p,Object r){if(r instanceof CreateNearbyPlaceRequest x){p.setName(x.name());p.setCategory(x.category());p.setAddress(x.address());p.setLatitude(x.latitude());p.setLongitude(x.longitude());}else{var x=(UpdateNearbyPlaceRequest)r;p.setName(x.name());p.setCategory(x.category());p.setAddress(x.address());p.setLatitude(x.latitude());p.setLongitude(x.longitude());}} @Transactional(readOnly=true) public List<NearbyPlaceResponse> list(Long id,String category){var d=destination(id);var result=category==null||category.isBlank()?places.findByDestination(d):places.findByDestinationAndCategoryIgnoreCase(d,category);return result.stream().map(NearbyPlaceMapper::toResponse).toList();} @Transactional(readOnly=true) public NearbyPlaceResponse get(Long d,Long id){return NearbyPlaceMapper.toResponse(place(d,id));} public NearbyPlaceResponse create(Long id,CreateNearbyPlaceRequest r){var p=new NearbyPlace();p.setDestination(destination(id));apply(p,r);return NearbyPlaceMapper.toResponse(places.save(p));} public NearbyPlaceResponse update(Long d,Long id,UpdateNearbyPlaceRequest r){var p=place(d,id);apply(p,r);return NearbyPlaceMapper.toResponse(places.save(p));} public void delete(Long d,Long id){places.delete(place(d,id));}}
